template <typename MaybeConstUserType>
struct Serializer<::ash::orca::mojom::TextQueryResponseDataView, MaybeConstUserType> {
  using UserType = typename std::remove_const<MaybeConstUserType>::type;
  using Traits = UnionTraits<::ash::orca::mojom::TextQueryResponseDataView, UserType>;

  static void Serialize(MaybeConstUserType& input,
                        MessageFragment<::ash::orca::mojom::internal::TextQueryResponse_Data>& fragment,
                        bool inlined) {
    if (CallIsNullIfExists<Traits>(input)) {
       if (inlined)
        fragment->set_null();
      return;
    }

    if (!inlined)
      fragment.Allocate();

    // TODO(azani): Handle unknown and objects.
    // Set the not-null flag.
    fragment->size = kUnionDataSize;
    fragment->tag = Traits::GetTag(input);
    switch (fragment->tag) {
      case ::ash::orca::mojom::TextQueryResponseDataView::Tag::kResults: {
        decltype(Traits::results(input))
            in_results = Traits::results(input);
        mojo::internal::MessageFragment<
            typename decltype(fragment->data.f_results)::BaseType>
            value_fragment(fragment.message());
        constexpr const mojo::internal::ContainerValidateParams& results_validate_params =
            mojo::internal::GetArrayValidator<0, false, nullptr>();
        mojo::internal::Serialize<mojo::ArrayDataView<::ash::orca::mojom::TextQueryResultDataView>>(
            in_results, value_fragment, &results_validate_params);
        MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
            value_fragment.is_null(),
            mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
            "null results in TextQueryResponse union");
        fragment->data.f_results.Set(
            value_fragment.is_null() ? nullptr : value_fragment.data());
        break;
      }
      case ::ash::orca::mojom::TextQueryResponseDataView::Tag::kError: {
        decltype(Traits::error(input))
            in_error = Traits::error(input);
        mojo::internal::MessageFragment<
            typename decltype(fragment->data.f_error)::BaseType>
            value_fragment(fragment.message());
        mojo::internal::Serialize<::ash::orca::mojom::TextQueryErrorDataView>(
            in_error, value_fragment);
        MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
            value_fragment.is_null(),
            mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
            "null error in TextQueryResponse union");
        fragment->data.f_error.Set(
            value_fragment.is_null() ? nullptr : value_fragment.data());
        break;
      }
    }
  }

  static bool Deserialize(::ash::orca::mojom::internal::TextQueryResponse_Data* input,
                          UserType* output,
                          Message* message) {
    if (!input || input->is_null())
      return CallSetToNullIfExists<Traits>(output);

    ::ash::orca::mojom::TextQueryResponseDataView data_view(input, message);
    return Traits::Read(data_view, output);
  }
};

